.pixel-button.button-secondary {
  --corner-cut: 9px;
  --button-shape: polygon(
    0 0, calc(100% - var(--corner-cut)) 0,
    calc(100% - var(--corner-cut)) var(--corner-cut), 100% var(--corner-cut),
    100% 100%, var(--corner-cut) 100%,
    var(--corner-cut) calc(100% - var(--corner-cut)), 0 calc(100% - var(--corner-cut))
  );
  color: #fff;
}

.pixel-button.button-secondary::before,
.pixel-button.button-secondary::after {
  clip-path: var(--button-shape);
  transition: clip-path .36s cubic-bezier(.22,1,.36,1);
}

.pixel-button.button-secondary::after {
  content: "";
  position: absolute;
  inset: 1px;
  z-index: -1;
  background: #000;
}

.pixel-button.button-secondary:is(:hover,:focus-visible,:active) {
  --corner-cut: 0px;
}
